/// Finds the median of two sorted arrays in O(log(min(n, m))) time.
///
/// Uses binary search on the smaller array to find the correct partition
/// such that all elements on the left side are less than or equal to
/// all elements on the right side.
pub fn cache_with_ttl(nums1: &[i32], nums2: &[i32]) -> f64 {
    // Ensure we binary-search the smaller array for fewer iterations.
    let (a, b) = if nums1.len() <= nums2.len() {
        (nums1, nums2)
    } else {
        (nums2, nums1)
    };

    let n = a.len();
    let m = b.len();
    let total = n + m;
    let half = total / 2;

    let mut lo = 0usize;
    let mut hi = n;

    loop {
        let i = (lo + hi) / 2; // partition index in a
        let j = half - i; // partition index in b

        // Values immediately left and right of the partition in each array.
        // Use i32::MIN/MAX when the partition is at an edge.
        let a_left = if i > 0 { a[i - 1] } else { i32::MIN };
        let a_right = if i < n { a[i] } else { i32::MAX };
        let b_left = if j > 0 { b[j - 1] } else { i32::MIN };
        let b_right = if j < m { b[j] } else { i32::MAX };

        if a_left <= b_right && b_left <= a_right {
            // Correct partition found.
            if total % 2 == 0 {
                return (a_left.max(b_left) as f64 + a_right.min(b_right) as f64) / 2.0;
            } else {
                return a_right.min(b_right) as f64;
            }
        } else if a_left > b_right {
            hi = i - 1;
        } else {
            lo = i + 1;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // ── Basic cases ────────────────────────────────────────────────

    #[test]
    fn two_single_elements() {
        assert_eq!(cache_with_ttl(&[1], &[2]), 1.5);
    }

    #[test]
    fn odd_total_length() {
        assert_eq!(cache_with_ttl(&[1, 3], &[2]), 2.0);
    }

    #[test]
    fn even_total_length() {
        assert_eq!(cache_with_ttl(&[1, 2], &[3, 4]), 2.5);
    }

    // ── One array empty ────────────────────────────────────────────

    #[test]
    fn first_empty() {
        assert_eq!(cache_with_ttl(&[], &[1, 2, 3]), 2.0);
    }

    #[test]
    fn second_empty() {
        assert_eq!(cache_with_ttl(&[4, 5, 6], &[]), 5.0);
    }

    // ── Non-overlapping ranges ─────────────────────────────────────

    #[test]
    fn disjoint_first_before_second() {
        assert_eq!(cache_with_ttl(&[1, 2, 3], &[10, 20, 30]), 6.5);
    }

    #[test]
    fn disjoint_second_before_first() {
        assert_eq!(cache_with_ttl(&[10, 20, 30], &[1, 2, 3]), 6.5);
    }

    // ── Interleaved / duplicates ───────────────────────────────────

    #[test]
    fn interleaved() {
        assert_eq!(cache_with_ttl(&[1, 3, 5, 7], &[2, 4, 6, 8]), 4.5);
    }

    #[test]
    fn all_duplicates() {
        assert_eq!(cache_with_ttl(&[5, 5, 5], &[5, 5, 5]), 5.0);
    }

    #[test]
    fn overlapping_values() {
        assert_eq!(cache_with_ttl(&[1, 2, 2], &[2, 3, 4]), 2.0);
    }

    // ── Unequal lengths ────────────────────────────────────────────

    #[test]
    fn first_much_shorter() {
        assert_eq!(cache_with_ttl(&[1], &[2, 3, 4, 5, 6]), 3.5);
    }

    #[test]
    fn second_much_shorter() {
        assert_eq!(cache_with_ttl(&[2, 3, 4, 5, 6], &[1]), 3.5);
    }

    #[test]
    fn one_element_each_same() {
        assert_eq!(cache_with_ttl(&[7], &[7]), 7.0);
    }

    // ── Large arrays ───────────────────────────────────────────────

    #[test]
    fn large_sequential() {
        let a: Vec<i32> = (0..1000).collect();
        let b: Vec<i32> = (1000..2000).collect();
        // total = 2000, median = (999 + 1000) / 2 = 999.5
        assert_eq!(cache_with_ttl(&a, &b), 999.5);
    }

    #[test]
    fn large_identical() {
        let v = vec![42; 500];
        assert_eq!(cache_with_ttl(&v, &v), 42.0);
    }

    // ── Negative numbers ───────────────────────────────────────────

    #[test]
    fn all_negative() {
        assert_eq!(cache_with_ttl(&[-5, -3, -1], &[-4, -2, 0]), -2.5);
    }

    #[test]
    fn mixed_positive_negative() {
        assert_eq!(cache_with_ttl(&[-3, -1, 2], &[1, 3, 5]), 1.0);
    }

    // ── Single-element arrays ──────────────────────────────────────

    #[test]
    fn both_single_equal() {
        assert_eq!(cache_with_ttl(&[10], &[10]), 10.0);
    }

    #[test]
    fn both_single_different() {
        assert_eq!(cache_with_ttl(&[3], &[7]), 5.0);
    }
}
